import { Vec2 } from "kaplay";
import { checkProjectileIntersection } from "../../game";
import { dt, k, layers, mainSoundVolume } from "../../main";
import { gameSoundService } from "../../services/audio/gameSoundService"
import { explosionEmitter } from "../../particles";
import { tags } from "../../tags";
import { registerHitAnimation } from "../../shared";
import { showDamageNumber } from "../../services/combat/damageService";
import { tryBounceProjectile } from "../../services/combat/projectileService";
import { registerBatchedEntityUpdate } from "../../services/core/entityUpdateService";
import { spawnThreatEncounter } from "../../services/enemies/enemyEncounterService";
import { getWorldVisual } from "../../visuals/worldVisualCatalog";
import { requirePrimaryVisualSprite } from "../../visuals/visualRepresentation";

const DAMAGE_SHRINE_VISUAL = getWorldVisual("damage-shrine");

interface DamageShrineProps {
	pos: Vec2;
	health: number;
	depleteRate: number; // damage per second that depletes
	enemyWaveMultiplier?: number;
	enemySpawnSpacing?: number;
	onComplete?: (pos: Vec2) => void;
	tags?: string[];
}

export function spawnDamageShrine(props: DamageShrineProps) {
	let activated = false;
	const shrine = k.add([
		k.pos(props.pos),
		k.sprite(requirePrimaryVisualSprite(DAMAGE_SHRINE_VISUAL)),
		k.anchor("center"),
		k.scale(DAMAGE_SHRINE_VISUAL.worldScale),
		k.opacity(1),
		k.animate(),
		{
			damageReceived: 0,
			maxHealth: props.health,
			depleteRate: props.depleteRate,
		},
		tags.enemy,
		tags.props,
		tags.gameLoop,
		...(props.tags ?? []),
	]);

	registerHitAnimation(shrine);

	// Add health bar above shrine
	const barWidth = 60;
	const barHeight = 8;
	const barBg = shrine.add([
		k.rect(barWidth, barHeight),
		k.pos(0, -50),
		k.anchor("center"),
		k.color(60, 60, 60),
		k.opacity(0.8),
		k.layer(layers.gameEffects),
	]);

	const barFill = shrine.add([
		k.rect(0, barHeight),
		k.pos(-barWidth / 2, -50),
		k.anchor("left"),
		k.color(255, 100, 100),
		k.opacity(0.9),
		k.layer(layers.gameEffects),
	]);

	registerBatchedEntityUpdate("enemies", shrine, () => {
		// Deplete damage over time
		shrine.damageReceived -= props.depleteRate * dt();
		if (shrine.damageReceived < 0) shrine.damageReceived = 0;

		// Check for projectile hits
		checkProjectileIntersection(shrine.pos, 24, tags.friendly, (p) => {
			if (!activated) {
				activated = true;
				const encounterCount = Math.max(0, Math.round(props.enemyWaveMultiplier ?? 0));
				for (let index = 0; index < encounterCount; index++) {
					const spawnPos = shrine.pos.add(
						k.Vec2.fromAngle(index * (360 / encounterCount) + 45).scale(180)
					);
					spawnThreatEncounter(spawnPos, props.enemySpawnSpacing ?? 48);
				}
			}
			// Add damage from projectile
			const damage = p.impactDamage ?? 1;
			shrine.damageReceived += damage;
			showDamageNumber(shrine.pos, damage);

			// Trigger hit animation
			if (shrine.animation) {
				shrine.animation.seek(0);
			}

			// Play hit sound
			gameSoundService.play("hit1", { volume: mainSoundVolume });

			if (!tryBounceProjectile(p, shrine)) k.destroy(p);
		});

		// Update health bar
		const progress = shrine.damageReceived / shrine.maxHealth;
		barFill.width = barWidth * progress;

		// Check if health threshold reached
		if (shrine.damageReceived >= shrine.maxHealth) {
			// Spawn particles
			explosionEmitter.pos = shrine.pos;
			explosionEmitter.emit(30);

			// Play sound
			gameSoundService.play("powerup1", { volume: mainSoundVolume });
			props.onComplete?.(shrine.pos.clone());

			// Destroy shrine
			k.destroy(shrine);
		}
	});

	return shrine;
}
